cd /home/vscode/rebaseline; python3 - <<'EOF'
import glob,re,os
tot=0; hist=0
for f in glob.glob('features/*.md')+glob.glob('initiatives/*.md')+glob.glob('decisions/*.md')+glob.glob('requests/*.md')+glob.glob('basis/**/*.md',recursive=True)+glob.glob('sessions/*.md'):
    t=open(f).read()
    w=len(t.split()); tot+=w
    m=re.search(r'\n## Document History\n(.*)$', t, re.S)
    if m: hist+=len(m.group(1).split())
print("corpus words (basis+working artifacts):",tot,"of which Document History:",hist, f"{100*hist/tot:.0f}%")
for d in ['basis','features','initiatives','decisions','requests','sessions','guidance','backlog','briefs']:
    fs=glob.glob(d+'/**/*.md',recursive=True)
    if fs: print(f"{d:12} files={len(fs):4} words={sum(len(open(x).read().split()) for x in fs)}")
EOF

cd /home/vscode/rebaseline; python3 - <<'EOF'
import glob,re
tot_t=0; tot_m=0; rows=0
byrole={}
for f in sorted(glob.glob('sessions/*-cost.md')):
    t=open(f).read(); n=0; tk=0; mn=0
    for line in t.splitlines():
        if line.startswith('| ') and '|---' not in line and 'Step |' not in line:
            c=[x.strip() for x in line.strip('|').split('|')]
            if len(c)<6: continue
            n+=1
            try: tk+=int(c[3])
            except: pass
            try: mn+=float(c[2])
            except: pass
            byrole.setdefault(c[1],[0,0]); byrole[c[1]][0]+=1
            try: byrole[c[1]][1]+=int(c[3])
            except: pass
    print(f"{f:40} rows={n:3} tokens={tk:9} minutes={mn:7.1f}")
    tot_t+=tk; tot_m+=mn; rows+=n
print("TOTAL",rows,"rows",tot_t,"tokens",round(tot_m,1),"minutes")
print()
for r,(c,tk) in sorted(byrole.items(), key=lambda x:-x[1][1]):
    print(f"{r:28} rows={c:3} tokens={tk:9}")
EOF
